package org.zhixiaoce.aperture;
import java.util.*;import android.app.Activity;import android.view.*;import android.widget.*;import org.json.*;
public class YearScoreAppendTest {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static CinemaCatalog.Item film(String id,String year,String rating)throws Exception{return new CinemaCatalog.Item(new JSONObject().put("vod_id",id).put("vod_name",id).put("vod_year",year).put("vod_score",rating).put("rating_source","豆瓣"));}
 static Object get(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 static void ordered(List<CinemaCatalog.Item> list){for(int i=1;i<list.size();i++){CinemaCatalog.Item a=list.get(i-1),b=list.get(i);int ay=CinemaOrder.year(a),by=CinemaOrder.year(b);check(ay>=by,"years descending after append");if(ay==by)check(CinemaOrder.douban(a)>=CinemaOrder.douban(b),"scores descending within a year");}}
 public static void main(String[] args)throws Exception{
  CinemaCatalog.Item oldHigh=film("old-high","2024","9.9"),newLow=film("new-low","2026","1.0"),newHigh=film("new-high","2026","8.9"),unknown=film("unknown","未知","10");unknown.updatedAt="2027-01-01";
  List<CinemaCatalog.Item> input=Arrays.asList(oldHigh,unknown,newLow,newHigh);for(String mode:Arrays.asList("latest","douban")){List<CinemaCatalog.Item> sorted=CinemaOrder.sorted(input,mode);check(sorted.equals(Arrays.asList(newHigh,newLow,oldHigh,unknown)),"year always precedes score, including Douban mode");}check(input.get(0)==oldHigh,"source list remains unchanged");
  CinemaCatalog.Item conflict=film("conflict","2023","10");conflict.releaseDate="2028-01-01";check(CinemaOrder.year(conflict)==2023,"explicit year wins over release-date conflict");CinemaCatalog.Item fallback=film("fallback","","8");fallback.releaseDate="2025-10-01";check(CinemaOrder.year(fallback)==2025,"missing year may use actual release year");check(CinemaOrder.year(unknown)==-1,"update time never invents production year");
  check(CinemaOrder.year(film("label","2026年（中国）","1"))==2026,"display year text accepted");CinemaCatalog.Item invalid=film("invalid","2026","NaN");check(CinemaOrder.sorted(Arrays.asList(invalid,newLow),"latest").get(0)==newLow,"invalid score placed last within year");
  Activity a=new Activity();LinearLayout root=new LinearLayout(a),content=new LinearLayout(a);ScrollView scroll=new ScrollView(a);scroll.addView(content);root.addView(scroll);Map<String,View> views=new HashMap<>();CinemaBrowsePanel p=new CinemaBrowsePanel(a,content,root,item->{View v=new View();views.put(item.id,v);return v;},()->{},()->{});GridLayout grid=(GridLayout)get(p,"grid");
  List<CinemaCatalog.Item> loaded=new ArrayList<>();for(int i=0;i<8;i++)loaded.add(film("initial"+i,"2024",String.valueOf(8-i*.2)));p.update(CinemaOrder.sorted(loaded,"latest"),false,"");grid.frame();p.focus("initial4",300);View.flushPosts();View anchor=views.get("initial4"),first=views.get("initial0");int offset=anchor.getTop()-scroll.getScrollY();
  for(int page=1;page<=3;page++){
   List<CinemaCatalog.Item> incoming=Arrays.asList(film("page"+page+"-old","2020","10"),film("page"+page+"-high","2026",String.valueOf(8+page*.2)),film("page"+page+"-low","2026",String.valueOf(page)),film("initial0","2028","10"));loaded=CinemaPaging.merge(loaded,incoming);List<CinemaCatalog.Item> sorted=CinemaOrder.sorted(loaded,"latest");ordered(sorted);p.update(sorted,true,"");grid.frame();check(anchor.hasFocus()&&anchor.getTop()-scroll.getScrollY()==offset,"resort preserves selected movie and viewport anchor");check(views.get("initial0")==first&&grid.getChildCount()==8+3*page,"append/resort retain tiles and ignore duplicate IDs");
  }
  check(CinemaOrder.sorted(loaded,"latest").get(0).id.equals("page3-high"),"late higher-scoring current-year film inserted above older pages");p.close();System.out.println(checks+" production year-first sorting and multi-page focus assertions passed");
 }
}
